module ripple_carry_adder (
    input [3:0] A,
    input [3:0] B,
    output [3:0] C
);

    wire [3:0] sum;
    wire [2:0] carry;

    full_adder fa0(A[0], B[0], 1'b0, sum[0], carry[0]);
    full_adder fa1(A[1], B[1], carry[0], sum[1], carry[1]);
    full_adder fa2(A[2], B[2], carry[1], sum[2], carry[2]);
    full_adder fa3(A[3], B[3], carry[2], sum[3], C[0]); // C[0] is the least significant bit

    // Assign the remaining bits of C
    assign C[1] = sum[1];
    assign C[2] = sum[2];
    assign C[3] = sum[3];

endmodule
