	input [3:0] B,
	input C_in,
	input clk,
	output [3:0] S,
	output C_out
);

	reg [3:0] S_reg;
	reg C_out_reg;

	always @(posedge clk) begin
		// calculate the sum of A, B, and C_in
		S_reg = A + B + C_in;

		// calculate the carry-out bit
