wire and1 = in[0] & in[1];
wire and2 = in[2] & in[3];
wire or1 = in[0] | in[1];
wire or2 = in[2] | in[3];
wire xor1 = in[0] ^ in[1];
wire xor2 = in[2] ^ in[3];

assign out_and = and1 | and2;
assign out_or = or1 & or2;
assign out_xor = xor1 & xor2;

// Sum module
wire [7:0] shift_sum = {1'b0, shift_reg};
wire [7:0] comb_sum = {1'b0, out_and, out_or, out_xor};

assign sum = shift_sum + comb_sum;

