module binary_adder(
    input [3:0] A,
    input [3:0] B,
    output [3:0] S,
    output C
);

    wire [3:0] c;
    wire [3:0] s;

    // Full adder for bit 0
    full_adder fa0(
        .a(A[0]),
        .b(B[0]),
        .c(1'b0),
        .s(s[0]),
        .co(c[0])
    );

    // Full adder for bit 1
    full_adder fa1(
        .a(A[1]),
        .b(B[1]),
        .c(c[0]),
        .s(s[1]),
        .co(c[1])
    );

    // Full adder for bit 2
    full_adder fa2(
        .a(A[2]),
        .b(B[2]),
        .c(c[1]),
        .s(s[2]),
        .co(c[2])
    );

    // Full adder for bit 3
    full_adder fa3(
        .a(A[3]),
        .b(B[3]),
        .c(c[2]),
        .s(s[3]),
        .co(C)
    );

    assign S = s;

endmodule
module full_adder(
    input a,
    input b,
    input c,
    output s,
    output co
);

    assign s = a ^ b ^ c;
    assign co = (a & b) | (b & c) | (c & a);

endmodule

