module adder4bit (
    input [3:0] A,
    input [3:0] B,
    input Cin,
    output [3:0] S,
    output Cout
);

    wire [3:0] sum;
    wire [3:0] carry;

    wire a3, a2, a1, a0;
    wire b3, b2, b1, b0;

    assign a3 = A[3];
    assign a2 = A[2];
    assign a1 = A[1];
    assign a0 = A[0];

    assign b3 = B[3];
    assign b2 = B[2];
    assign b1 = B[1];
    assign b0 = B[0];

    // Full adder
    full_adder fa0 (.A(a0), .B(b0), .Cin(Cin), .S(sum[0]), .Cout(carry[0]));
    full_adder fa1 (.A(a1), .B(b1), .Cin(carry[0]), .S(sum[1]), .Cout(carry[1]));
    full_adder fa2 (.A(a2), .B(b2), .Cin(carry[1]), .S(sum[2]), .Cout(carry[2]));
    full_adder fa3 (.A(a3), .B(b3), .Cin(carry[2]), .S(sum[3]), .Cout(Cout));

    assign S = sum;

endmodule
