module mux4to1 (
    input  A,
    input  B,
    input  C,
    input  D,
    input  [1:0] S,
    output Y
);

    wire not_S0, not_S1;
    wire and1, and2, and3, and4;
    wire or1, or2;

    // Invert select signals
    not (not_S0, S[0]);
    not (not_S1, S[1]);

    // AND gates
    and (and1, A, not_S1, not_S0);
    and (and2, B, not_S1, S[0]);
    and (and3, C, S[1], not_S0);
    and (and4, D, S[1], S[0]);

    // OR gates
    or (or1, and1, and2);
    or (or2, and3, and4);

    // Final output
    or (Y, or1, or2);

endmodule

