module adder_4bit_5bit_out (
    // Inputs
    input [3:0] a,
    input [4:0] b,
    // Outputs
    output [4:0] sum
);

    wire [3:0] carry_out;
    wire [3:0] sum_internal;

    assign sum_internal[0] = a[0] ^ b[0];
    assign carry_out[0] = (a[0] & b[0]);

    assign sum_internal[1] = a[1] ^ b[1] ^ carry_out[0];
    assign carry_out[1] = (a[1] & b[1]) | (a[1] & carry_out[0]) | (b[1] & carry_out[0]);

    assign sum_internal[2] = a[2] ^ b[2] ^ carry_out[1];
    assign carry_out[2] = (a[2] & b[2]) | (a[2] & carry_out[1]) | (b[2] & carry_out[1]);

    assign sum_internal[3] = a[3] ^ b[3] ^ carry_out[2];
    assign carry_out[3] = (a[3] & b[3]) | (a[3] & carry_out[2]) | (b[3] & carry_out[2]);

    assign sum[0] = sum_internal[0];
    assign sum[1] = sum_internal[1];
    assign sum[2] = sum_internal[2];
    assign sum[3] = sum_internal[3];
    assign sum[4] = b[4] | carry_out[3];

endmodule

