module acciones_to_bcd(
	 input clk,
	 input rst,
	 input [1:0] piso, input [1:0] accion, input puertas, output reg [3:0] BCD1,
	 output reg [3:0] BCD2,
	 output reg [3:0] BCD3,
	 output reg [3:0] BCD4
    );

initial begin
	BCD4 = 1;
	BCD3 = 9;
	BCD2 = 6;
	BCD1 = 0;
end

always @ (posedge clk)
	begin
		if (rst == 1)
			begin
				BCD4 = 4'b1110;
				#10 BCD4 = 4'b0001;
				BCD3 = 4'b0110;
				#10 BCD3 = 4'b1001;
			end
		else
			begin
				if (piso == 2'b00)
					BCD4 = 4'b0001;
				else if (piso == 2'b01)
					BCD4 = 4'b0010;
				else if (piso == 2'b10)
					BCD4 = 4'b0011;
				else
					BCD4 = 4'b0100;
			end
	end

always @ (posedge clk)
	begin
		if (rst == 1)
			begin
				BCD1 = 4'b1111;
				#10 BCD1 = 4'b0000;
			end
		else
			begin
				if (accion == 2'b00)
					BCD1 = 4'b0000;
				else if (accion == 2'b01)
					BCD1 = 4'b0101;
				else if (accion == 2'b10)
					BCD1 = 4'b1000;
				else
					BCD1 = 0;
			end
	end

always @ (posedge clk)
	begin
		if (rst == 1)
			begin
				BCD2 = 4'b1001;
				#10 BCD2 = 4'b0110;
			end
		else
			begin
				if (puertas == 1'b0)
