module SSCG (
  input ref_clk,
  input [7:0] mod_rate,
  input rst,
  output reg ssc_clk
);

  reg [7:0] lfsr;
  reg [7:0] seed = 8'hFF; // unique seed value for each instance
  reg [7:0] mod_counter = 0;

  always @(posedge ref_clk or posedge rst) begin
    if (rst) begin
      lfsr <= seed;
      mod_counter <= 0;
      ssc_clk <= 1'b0;
    end else begin
      lfsr <= {lfsr[6:0], lfsr[7]^lfsr[2]^lfsr[1]^lfsr[0]};
      mod_counter <= mod_counter + 1;
      if (mod_counter == mod_rate) begin
        ssc_clk <= ~ssc_clk;
        mod_counter <= 0;
      end
    end
  end

endmodule

