module adder16(A, B, Cin, Sum, Cout);
  input [15:0] A;
  input [15:0] B;
  input Cin;
  output [15:0] Sum;
  output Cout;

  wire [15:0] carry;
  wire [15:0] temp_sum;

  assign temp_sum[0] = A[0] ^ B[0] ^ Cin;
  assign carry[0] = (A[0] & B[0]) | (A[0] & Cin) | (B[0] & Cin);

  genvar i;
  generate
