    input  VPWR ;
    input  VGND ;
    output Q    ;
    output Q_N  ;
    input  CLK  ;
    input  D    ;
    input  SET_B;

    // Local signals
    reg    buf_Q        ;
    wire   SET          ;
    reg    notifier     ;
    wire   D_delayed    ;
    wire   SET_B_delayed;
    wire   CLK_delayed  ;
