            buf_Q <= 1'b0;
            notifier <= 1'b0;
        end else if (!cond0 || !cond1) begin
            buf_Q <= 1'b1;
            notifier <= 1'b1;
        end else if (notifier) begin
            buf_Q <= D_delayed;
            notifier <= 1'b0;
