frequency_analyzer_b468ac09.rtl_code:
module frequency_analyzer #
(
    parameter FREQUENCY0 = 9000,
    parameter FREQUENCY1 = 11000,
    parameter FREQUENCY0_DEVIATION = 20,
    parameter FREQUENCY1_DEVIATION = 20,
    parameter CLOCK_FREQUENCY = 50000000
)
(
    input wire sample_data,
    input wire clock,
    input wire enable,
    input wire clear,
    output reg[31:0] f0_value,
    output reg[31:0] f1_value
);

    reg[31:0] f0_count = 0;
    reg[31:0] f1_count = 0;
    reg[31:0] f0_accumulator = 0;
    reg[31:0] f1_accumulator = 0;
    reg[31:0] f0_frequency = 0;
    reg[31:0] f1_frequency = 0;
    reg[31:0] f0_deviation = FREQUENCY0_DEVIATION;
    reg[31:0] f1_deviation = FREQUENCY1_DEVIATION;
    reg[1:0] state = 0;

    always @(posedge clock) begin
        if (clear) begin
            f0_count <= 0;
            f1_count <= 0;
            f0_accumulator <= 0;
            f1_accumulator <= 0;
            f0_frequency <= 0;
            f1_frequency <= 0;
            f0_deviation <= FREQUENCY0_DEVIATION;
            f1_deviation <= FREQUENCY1_DEVIATION;
            state <= 0;
        end
        else if (enable) begin
            case (state)
                0: begin // Counting
                    if (sample_data) begin
                        f0_accumulator <= f0_accumulator + 1;
                        f1_accumulator <= f1_accumulator + 1;
                    end
                    f0_count <= f0_count + 1;
                    f1_count <= f1_count + 1;
                    if (f0_count == ((CLOCK_FREQUENCY/FREQUENCY0)/2)) begin
                        f0_frequency <= (CLOCK_FREQUENCY/f0_count);
                        state <= 1;
                    end
                    else if (f1_count == ((CLOCK_FREQUENCY/FREQUENCY1)/2)) begin
                        f1_frequency <= (CLOCK_FREQUENCY/f1_count);
                        state <= 2;
                    end
                end
                1: begin // Checking first frequency
                    if (f0_frequency >= FREQUENCY0 - f0_deviation && f0_frequency <= FREQUENCY0 + f0_deviation) begin
                        f0_value <= f0_frequency;
                    end
                    if (f1_frequency >= FREQUENCY1 - f1_deviation && f1_frequency <= FREQUENCY1 + f1_deviation) begin
                        f1_value <= f1_frequency;
                    end
                    state <= 0;
                end
                2: begin // Checking second frequency
                    if (f0_frequency >= FREQUENCY0 - f0_deviation && f0_frequency <= FREQUENCY0 + f0_deviation) begin
                        f0_value <= f0_frequency;
                    end
                    if (f1_frequency >= FREQUENCY1 - f1_deviation && f1_frequency <= FREQUENCY1 + f1_deviation) begin
                        f1_value <= f1_frequency;
                    end
                    state <= 0;
                end
            endcase
        end
    end

endmodule

