);

always @(select) begin
    if (enable) begin
        case (select)
            2'b00: out = 16'h0001;
            2'b01: out = 16'h0002;
            2'b10: out = 16'h0004;
            2'b11: out = 16'h0008;
        endcase
    end else begin
        out = 16'b0;
    end
end

endmodule

module top_module (
