        case(shift_ctrl)
            4'b0000: Q = D << 1;
            4'b0001: Q = D << 2;
            4'b0010: Q = D << 4;
            4'b0011: Q = D << 8;
            4'b0100: Q = D >> 1;
            4'b0101: Q = D >> 2;
            4'b0110: Q = D >> 4;
            4'b0111: Q = D >> 8;
