module counter_4bit_sync_reset(CLK, EN, RST, LOAD, Q, QBAR);
  input CLK, EN, RST, LOAD;
  output [3:0] Q;
  output [3:0] QBAR;

  wire [3:0] Q_next;
  wire [3:0] QBAR_next;

