if (TARGET == "XILINX") begin

    if (CLOCK_INPUT_STYLE == "BUFG") begin

        BUFG
        clk_bufg (
            .I(input_clk),
            .O(clk_int)
        );

        assign clk_io = clk_int;
        assign output_clk = clk_int;

    end else if (CLOCK_INPUT_STYLE == "BUFR") begin

        assign clk_int = input_clk;

        BUFIO
        clk_bufio (
            .I(clk_int),
            .O(clk_io)
        );

        BUFR #(
            .BUFR_DIVIDE("BYPASS")
        )
        clk_bufr (
            .I(clk_int),
            .O(output_clk),
            .CE(1'b1),
            .CLR(1'b0)
        );

    end else if (CLOCK_INPUT_STYLE == "BUFIO") begin

        assign clk_int = input_clk;

        BUFIO
        clk_bufio (
            .I(clk_int),
            .O(clk_io)
        );

        BUFG
        clk_bufg (
            .I(clk_int),
            .O(output_clk)
        );

    end else if (CLOCK_INPUT_STYLE == "BUFIO2") begin

        BUFIO2 #(
            .DIVIDE(1),
            .DIVIDE_BYPASS("TRUE"),
            .I_INVERT("FALSE"),
            .USE_DOUBLER("FALSE")
        )
        clk_bufio (
