            .IOCLK(clk_io),
            .SERDESSTROBE()
        );

        BUFG
        clk_bufg (
            .I(clk_int),
            .O(output_clk)
        );

    end

end else begin

    assign clk_io = input_clk;

    assign clk_int = input_clk;
    assign output_clk = clk_int;

end

endgenerate


