module top_module (
    input [7:0] d, c, b, a, // Inputs to the maximum module
    input [7:0] x, y, // Inputs to the addition module
    input select, // Selects which module to use as input to the functional module
    output [7:0] sum, // Output of the functional module
    output overflow // Output of the addition module indicating overflow
);

    wire [7:0] max_val; // Intermediate wire to hold the output of the maximum module
    wire [7:0] add_val; // Intermediate wire to hold the output of the addition module
    reg [7:0] final_sum; // Register to break the feedback path

