module top_module(
    input wire [15:0] in,
    input wire clk,
    output reg [7:0] out_hi,
    output reg [7:0] out_lo
);

    // Pipeline registers
    reg [15:0] in_reg;
    reg [7:0] out_hi_reg;
    reg [7:0] out_lo_reg;

    // Barrel shifter
    reg [15:0] shifted_in;
    always @(*) begin
        shifted_in = in_reg >> 8;
    end

    // Multiplexer
    always @(*) begin
        if (in_reg[7:0] == 0) begin
            out_hi_reg = shifted_in[15:8];
        end else begin
            out_hi_reg = in_reg[15:8];
        end
        out_lo_reg = in_reg[7:0];
    end

    // Pipeline stages
    always @(posedge clk) begin
        in_reg <= in;
    end

    always @(*) begin
        out_hi <= out_hi_reg;
        out_lo <= out_lo_reg;
    end

endmodule

