module ModmCountr
   #(parameter M=50000000) (
    input wire clk, reset,
    output wire max_tick,
    output wire [log2(M)-1:0] q
   );

   localparam N = log2(M);   reg [N-1:0] r_reg;
   wire [N-1:0] r_next;

   always @(posedge clk, posedge reset)
      if (reset)
         r_reg <= 0;
      else
