module two_input_gate (A, B, Y);

input A, B;
output Y;

wire not_A, not_B, and_AB, and_notA_notB;

// Invert A and B
not (not_A, A);
not (not_B, B);

// Compute A AND B and NOT A AND NOT B
and (and_AB, A, B);
and (and_notA_notB, not_A, not_B);

// Compute Y = (A AND B) OR (NOT A AND NOT B)
or (Y, and_AB, and_notA_notB);

endmodule

