module top_module (
    input signed [3:0] A,
    input signed [3:0] B,
    input EN,
    output [15:0] Q,
    output C
);

    wire [3:0] abs_A, abs_B;
    wire eq, gt, lt;
    reg [1:0] sel;

    signed_mag_comp comp(.A(A), .B(B), .eq(eq), .gt(gt), .lt(lt), .abs_A(abs_A), .abs_B(abs_B));
    decoder dec(.SEL(sel), .EN(EN), .Q(Q));

    assign C = eq;

    always @(*) begin
        if (EN) begin
            if (eq) begin
                sel = 2'b00;
            end else if (gt) begin
                sel = 2'b01;
            end else if (lt) begin
                sel = 2'b10;
            end
        end else begin
