      S2: begin
        green_light <= 0;
        yellow_light <= 0;
        red_light <= 1;
        next_state <= S3;
      end
      S3: begin
        green_light <= 0;
        yellow_light <= 1;
        red_light <= 0;
        next_state <= S0;
      end
      default: begin
        green_light <= 0;
        yellow_light <= 0;
        red_light <= 0;
        next_state <= S0;
      end
    endcase
