module bitwise_and (
    input [3:0] in1,
    input [3:0] in2,
    output [3:0] out,
    input VPWR, VGND, VPB, VNB
);

wire [3:0] not_in1;
wire [3:0] not_in2;
wire [3:0] not_out;

// invert the inputs
assign not_in1 = ~in1;
assign not_in2 = ~in2;

