module top_module (
    input clk,
    input reset,           // Synchronous active-high reset
    input [7:0] D,         // 8-bit input for the bit_reverser module
    output reg [3:0] out   // 4-bit output from the bitwise OR module
);

    wire [3:0] ring_out;
    wire [7:0] reverse_out;
    wire [3:0] or_out;

    bit_reverser reverse_inst(
        .D(D),
        .Q(reverse_out)
    );

    ring_counter ring_inst(
        .clk(clk),
        .reset(reset),
        .Q(ring_out)
    );

    bitwise_OR or_inst(
        .A(ring_out),
        .B(reverse_out[3:0]),
        .Y(or_out)
    );

    always @(posedge clk) begin
        if (reset) begin
            out <= 4'b0000;
        end else begin
            out <= or_out;
        end
    end

