module top_module (
    input clk,
    input reset,
    input [7:0] d1,
    input [7:0] d2,
    output reg [7:0] q
);

    wire [7:0] result1;
    wire [7:0] result2;
    wire [7:0] result3;

    bitwise_logic logic_unit (
        .a(d1),
        .b(d2),
        .op(2'b00),     // Bitwise AND
        .result(result1)
    );

    register reg1 (
        .clk(clk),
        .reset(reset),
        .d(result1),
        .q(q)
    );

    bitwise_logic logic_unit2 (
        .a(d1),
        .b(d2),
        .op(2'b01),     // Bitwise OR
        .result(result2)
    );

    register reg2 (
        .clk(clk),
        .reset(reset),
        .d(result2),
        .q(result2)
    );

    bitwise_logic logic_unit3 (
        .a(result1),
        .b(result2),
        .op(2'b10),     // Bitwise XOR
        .result(result3)
    );

    register reg3 (
