module pulse_generator(
    input reset,
    output reg pulse,
    input clk // Corrected the missing input port `clk`
);

    reg [24:0] counter;
    parameter CLK_FREQ = 50_000_000; // 50 MHz clock frequency
    parameter PULSE_FREQ = 1_000; // 1 kHz pulse frequency

    always @(posedge clk) begin
        if (reset) begin
            pulse <= 0;
            counter <= 0;
        end
        else begin
            counter <= counter + 1;
            if (counter >= (CLK_FREQ/PULSE_FREQ)/2) begin
                pulse <= ~pulse;
                counter <= 0;
            end
        end
    end

endmodule

