module top_module (
    input wire [15:0] in,
    input wire [7:0] a,
    input wire [7:0] b,
    output wire [7:0] out
);

    wire [15:0] mult_out;
    wire [7:0] out_hi, out_lo;
    wire [7:0] add_out;

    multiplication mult_inst(
        .a(a),
        .b(b),
        .product(mult_out)
    );

    byte_splitter byte_inst(
        .in(mult_out),
        .out_hi(out_hi),
        .out_lo(out_lo)
    );

