    // Full adder for third least significant bit
    full_adder FA2(A[2], B[2], temp_carry[1], temp_sum[2], temp_carry[2]);

    // Full adder for most significant bit
    full_adder FA3(A[3], B[3], temp_carry[2], temp_sum[3], Cout);

    assign Sum = temp_sum;

endmodule
